import struct
import sys

def custom_gmtime(ts):
    SECONDS_PER_DAY = 86400
    days = ts // SECONDS_PER_DAY
    rem = ts % SECONDS_PER_DAY
    if rem < 0:
        rem += SECONDS_PER_DAY
        days -= 1
    hour = rem // 3600
    rem %= 3600
    minute = rem // 60
    sec = rem % 60
    
    days += 719468
    era = (days if days >= 0 else days - 146096) // 146097
    doe = days - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    if m <= 2:
        y += 1
        
    return {
        'year': y, 'mon': m - 1, 'mday': d,
        'hour': hour, 'minute': minute, 'sec': sec
    }

def get_ascii_repr(val):
    """8바이트 정수를 ASCII 문자열로 디코딩하여 직관적인 분석을 돕습니다."""
    try:
        b = struct.pack('<q', val)
        return "'" + "".join(chr(x) if 32 <= x <= 126 else '.' for x in b) + "'"
    except:
        return "'........'"

def run_time_machine_vm(timestamps, input_payload=b""):
    mem = bytearray(69 * 8)
    
    def get_qword(idx):
        if idx < 0 or idx >= 69: return 0
        return struct.unpack('<q', mem[idx*8:idx*8+8])[0]

    def set_qword(idx, val):
        if idx < 0 or idx >= 69: return
        val = val & 0xFFFFFFFFFFFFFFFF
        if val & 0x8000000000000000:
            val -= 0x10000000000000000
        mem[idx*8:idx*8+8] = struct.pack('<q', val)

    start_ip = 0
    for i, ts in enumerate(timestamps):
        dt = custom_gmtime(ts)
        if dt['year'] == 117 and dt['mon'] == 8 and dt['mday'] == 10:
            start_ip = i
            break
            
    if start_ip == 0: start_ip = 117
    set_qword(1, start_ip)
    set_qword(3, 0)
    input_ptr = 0
    
    def get_dest_idx(h, m):
        sp = get_qword(3)
        if 0 <= h <= 9: return sp + m + 8
        elif 10 <= h <= 19: return sp - m + 8
        else: return (m % 7) + 1

    def get_src_val(h, s, y):
        mode = h % 10
        sp = get_qword(3)
        if mode == 0: return get_qword(sp + s + 8)
        elif mode == 1: return get_qword(sp - s + 8)
        elif mode == 2: return get_qword((s % 7) + 1)
        else: return y

    def dump_regs():
        regs = []
        for i in range(4, 8):
            val = get_qword(i)
            regs.append(f"R{i}:{val} {get_ascii_repr(val)}")
        return f"[REGS] IP:{get_qword(1):04d} LR:{get_qword(2):04d} SP:{get_qword(3):04d} | " + " | ".join(regs)

    print("="*80)
    print(f"🚀 Time Machine Advanced VM Tracer Started (Start IP: {start_ip})")
    print("="*80)

    while True:
        ip = get_qword(1)
        if ip < 0 or ip >= len(timestamps):
            print(f"\n[!] HALT: Instruction Pointer ({ip}) out of bounds.")
            break

        ts = timestamps[ip]
        set_qword(1, ip + 1)

        dt = custom_gmtime(ts)
        year, mon, mday = dt['year'], dt['mon'], dt['mday']
        hour, minute, sec = dt['hour'], dt['minute'], dt['sec']

        print(f"\n[{ip:04d}] Ts: {ts} => {year:04d}.{mon+1:02d}.{mday:02d} {hour:02d}:{minute:02d}:{sec:02d}")
        print(dump_regs())

        dest_idx = get_dest_idx(hour, minute)
        src_val = get_src_val(hour, sec, year)
        
        if mon == 0:
            if mday == 20: 
                print(f"  ➜ MOV  [idx:{dest_idx}], {src_val} {get_ascii_repr(src_val)}")
                set_qword(dest_idx, src_val)
            elif mday == 21: 
                sp = get_qword(3)
                print(f"  ➜ PUSH {src_val} {get_ascii_repr(src_val)} (into SP idx:{sp+8})")
                set_qword(sp + 8, src_val)
                set_qword(3, sp + 1)
            elif mday == 22: 
                sp = get_qword(3) - 1
                set_qword(3, sp)
                val = get_qword(sp + 8)
                print(f"  ➜ POP  [idx:{dest_idx}] (from SP idx:{sp+8}, val:{val} {get_ascii_repr(val)})")
                set_qword(dest_idx, val)
                
        elif mon == 2:
            if mday == 1: 
                res = get_qword(dest_idx) + src_val
                print(f"  ➜ ADD  [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
            elif mday == 16: 
                res = get_qword(dest_idx) - src_val
                print(f"  ➜ SUB  [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
                
        elif mon == 3:
            if mday == 3: 
                res = get_qword(dest_idx) * src_val
                print(f"  ➜ MUL  [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
            elif mday == 19: 
                res = get_qword(dest_idx) // src_val if src_val != 0 else 0
                print(f"  ➜ DIV  [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
                
        elif mon == 4:
            if mday == 1: 
                res = get_qword(dest_idx) ^ src_val
                print(f"  ➜ XOR  [idx:{dest_idx}], {src_val} {get_ascii_repr(src_val)} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
            elif mday == 5: 
                res = get_qword(dest_idx) & src_val
                print(f"  ➜ AND  [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
            elif mday == 8: 
                res = get_qword(dest_idx) | src_val
                print(f"  ➜ OR   [idx:{dest_idx}], {src_val} (Result: {res} {get_ascii_repr(res)})")
                set_qword(dest_idx, res)
                
        elif mon == 7:
            if mday == 15: 
                shift = src_val & 0x3f
                res = get_qword(dest_idx) << shift
                print(f"  ➜ SHL  [idx:{dest_idx}], {shift}")
                set_qword(dest_idx, res)
            elif mday == 17: 
                shift = src_val & 0x3f
                res = get_qword(dest_idx) >> shift
                print(f"  ➜ SHR  [idx:{dest_idx}], {shift}")
                set_qword(dest_idx, res)
                
        elif mon == 8:
            if mday == 10: 
                cond_mode = hour % 10
                reg_idx = (sec % 7) + 1
                cond_val = get_qword(reg_idx)
                
                cond = False
                if cond_mode == 0: cond = (cond_val == 0)
                elif cond_mode == 1: cond = (cond_val > 0)
                elif cond_mode == 2: cond = (cond_val < 0)
                else: cond = True
                
                print(f"  ➜ JMP  Condition Mode: {cond_mode} (Value: {cond_val}) -> Match: {cond}")
                if cond:
                    target = get_qword((minute % 7) + 1) if (0 <= hour <= 9) else year
                    curr_ip = get_qword(1)
                    print(f"     => Branch Taken! Target: {target}. Saving LR(R2) = {curr_ip}")
                    set_qword(2, curr_ip)
                    set_qword(1, target)
                    
        elif mon == 10:
            if mday == 7: 
                nbytes = src_val
                data = input_payload[input_ptr : input_ptr+nbytes]
                input_ptr += len(data)
                
                if len(data) < nbytes:
                    data += b'\x00' * (nbytes - len(data))
                    
                offset = dest_idx * 8
                mem[offset : offset+nbytes] = data
                print(f"  ➜ SYS_READ {nbytes} bytes -> Mem[idx:{dest_idx}] (Read: {data})")
                
            elif mday == 9: 
                nbytes = src_val
                offset = dest_idx * 8
                out_data = mem[offset : offset+nbytes]
                try:
                    str_data = out_data.decode('utf-8').rstrip('\x00')
                    print(f"  ➜ SYS_WRITE ({nbytes} bytes) from Mem[idx:{dest_idx}]: {repr(str_data)}")
                except:
                    print(f"  ➜ SYS_WRITE ({nbytes} bytes) from Mem[idx:{dest_idx}]: {out_data}")
                
        elif mon == 11 and mday == 31: 
            print(f"  ➜ HALT (Dec 31 reached)")
            break
        
        else:
            print(f"  [?] NOP or Unknown Instruction Data: {ts}")

